function imu = simulate_imu(truth, config)
%SIMULATE_IMU Generate virtual accelerometer and gyroscope measurements.
%
% Inputs:
%   truth  - Ground-truth structure generated by
%            generate_truth_trajectory.m
%
%   config - IMU configuration structure generated by
%            create_imu_config.m
%
% Output:
%   imu    - Structure containing:
%            measured acceleration
%            measured yaw rate
%            sensor biases
%            white measurement noise
%            measurement errors
%
% Measurement models:
%
%   a_measured = a_true + accelerometer_bias + accelerometer_noise
%
%   gyro_measured = gyro_true + gyro_bias + gyro_noise
%
% Bias evolution:
%
%   b(k+1) = b(k) + sigma_rw * sqrt(dt) * random_normal_value

    %% Validate the required ground-truth fields

    required_truth_fields = { ...
        'time', ...
        'dt', ...
        'acceleration_body_x', ...
        'acceleration_body_y', ...
        'yaw_rate'};

    for field_index = 1:numel(required_truth_fields)

        current_field = required_truth_fields{field_index};

        if ~isfield(truth, current_field)
            error( ...
                'The truth structure does not contain the required field "%s".', ...
                current_field);
        end
    end

    %% Basic dimensions

    time = truth.time;
    dt = truth.dt;
    number_of_samples = numel(time);

    if number_of_samples < 2
        error('At least two simulation samples are required.');
    end

    %% Set the random seed

    rng(config.random_seed, 'twister');

    %% Preallocate accelerometer biases

    accelerometer_bias_x = zeros(number_of_samples, 1);
    accelerometer_bias_y = zeros(number_of_samples, 1);

    accelerometer_bias_x(1) = ...
        config.accelerometer.initial_bias_x;

    accelerometer_bias_y(1) = ...
        config.accelerometer.initial_bias_y;

    %% Generate accelerometer-bias random walks

    accelerometer_bias_increment_x = ...
        config.accelerometer.bias_random_walk_std_x ...
        * sqrt(dt) ...
        * randn(number_of_samples - 1, 1);

    accelerometer_bias_increment_y = ...
        config.accelerometer.bias_random_walk_std_y ...
        * sqrt(dt) ...
        * randn(number_of_samples - 1, 1);

    accelerometer_bias_x(2:end) = ...
        accelerometer_bias_x(1) ...
        + cumsum(accelerometer_bias_increment_x);

    accelerometer_bias_y(2:end) = ...
        accelerometer_bias_y(1) ...
        + cumsum(accelerometer_bias_increment_y);

    %% Generate accelerometer white noise

    accelerometer_noise_x = ...
        config.accelerometer.measurement_noise_std_x ...
        * randn(number_of_samples, 1);

    accelerometer_noise_y = ...
        config.accelerometer.measurement_noise_std_y ...
        * randn(number_of_samples, 1);

    %% Generate accelerometer measurements

    acceleration_x_measured = ...
        truth.acceleration_body_x ...
        + accelerometer_bias_x ...
        + accelerometer_noise_x;

    acceleration_y_measured = ...
        truth.acceleration_body_y ...
        + accelerometer_bias_y ...
        + accelerometer_noise_y;

    %% Preallocate gyroscope bias

    gyroscope_bias = zeros(number_of_samples, 1);

    gyroscope_bias(1) = ...
        config.gyroscope.initial_bias;

    %% Generate gyroscope-bias random walk

    gyroscope_bias_increment = ...
        config.gyroscope.bias_random_walk_std ...
        * sqrt(dt) ...
        * randn(number_of_samples - 1, 1);

    gyroscope_bias(2:end) = ...
        gyroscope_bias(1) ...
        + cumsum(gyroscope_bias_increment);

    %% Generate gyroscope white noise

    gyroscope_noise = ...
        config.gyroscope.measurement_noise_std ...
        * randn(number_of_samples, 1);

    %% Generate gyroscope measurement

    yaw_rate_measured = ...
        truth.yaw_rate ...
        + gyroscope_bias ...
        + gyroscope_noise;

    %% Calculate total measurement errors

    accelerometer_error_x = ...
        acceleration_x_measured ...
        - truth.acceleration_body_x;

    accelerometer_error_y = ...
        acceleration_y_measured ...
        - truth.acceleration_body_y;

    gyroscope_error = ...
        yaw_rate_measured ...
        - truth.yaw_rate;

    %% Store outputs

    imu.time = time;
    imu.dt = dt;
    imu.sampling_frequency = 1 / dt;

    imu.acceleration_x_measured = acceleration_x_measured;
    imu.acceleration_y_measured = acceleration_y_measured;
    imu.yaw_rate_measured = yaw_rate_measured;

    imu.accelerometer_bias_x = accelerometer_bias_x;
    imu.accelerometer_bias_y = accelerometer_bias_y;
    imu.gyroscope_bias = gyroscope_bias;

    imu.accelerometer_noise_x = accelerometer_noise_x;
    imu.accelerometer_noise_y = accelerometer_noise_y;
    imu.gyroscope_noise = gyroscope_noise;

    imu.accelerometer_error_x = accelerometer_error_x;
    imu.accelerometer_error_y = accelerometer_error_y;
    imu.gyroscope_error = gyroscope_error;

    imu.accelerometer_bias_increment_x = ...
        accelerometer_bias_increment_x;

    imu.accelerometer_bias_increment_y = ...
        accelerometer_bias_increment_y;

    imu.gyroscope_bias_increment = ...
        gyroscope_bias_increment;

    imu.config = config;
end